
%Q8 Spatial Linear Filtering

clear; clc; close all;

%Read image
I = imread(['HW1Q8_original_image.jpg']);

I = double(I);

%Mask sizes
m_values = [3, 9];

for k = 1:length(m_values) %[output:group:82921796]
    m = m_values(k);

    w = ones(m, m) / (m^2);

    Ifilt = conv2(I, w, 'same');

    %Display results
    figure; %[output:745de81b] %[output:89aec66d]
    imshow(uint8(Ifilt)); %[output:745de81b] %[output:89aec66d]
    title(['Filtered Image with m = ', num2str(m)]);

    imwrite(uint8(Ifilt), ['Q8_filtered_m', num2str(m), '.jpg']);
end %[output:group:82921796]


